\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Warm Advocacy Color Theme ──
\definecolor{bgposter}{HTML}{1C1108}       % deep dark warm brown
\definecolor{primary}{HTML}{E85D3A}         % warm burnt orange
\definecolor{secondary}{HTML}{F5A623}       % golden amber
\definecolor{accent}{HTML}{D84315}          % deep red-orange
\definecolor{cardbg}{HTML}{2A1E14}          % card tinted dark
\definecolor{cardtitlebg}{HTML}{3A2818}     % card title bar tint
\definecolor{statbg}{HTML}{2E1F12}          % stat callout background
\definecolor{statgold}{HTML}{F7DC6F}        % bright gold for stat numbers
\definecolor{textwarm}{HTML}{FDEBD0}        % warm cream text
\definecolor{textmuted}{HTML}{C4A882}       % muted warm text
\definecolor{actionbg}{HTML}{332418}        % action card background
\definecolor{donategreen}{HTML}{27AE60}     % green accent for CTA
\definecolor{pillaraccent}{HTML}{E67E22}    % orange accent for pillar highlights

\pagecolor{bgposter}
\color{textwarm}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=5pt, parsep=0pt, topsep=0pt,
  label={\color{secondary}$\blacktriangleright$}}

% ── Card styles ──
\tcbset{
  warmcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardtitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={primary!60},
    valign=top, drop shadow={opacity=0.25},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardtitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={secondary!60},
    valign=top, drop shadow={opacity=0.25},
  },
  actioncard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=actionbg,
    borderline west={5pt}{0pt}{donategreen},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{donategreen},
    coltitle=donategreen, colbacktitle=cardtitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={donategreen!60},
    valign=top, drop shadow={opacity=0.25},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════
% TITLE BAR (rows 0-4, span=3)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=accent, colframe=accent, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{88}{106}\selectfont\bfseries HUNGER DOESN'T WAIT}\\[10pt]
  {\fontsize{46}{56}\selectfont\color{white!85} Together We Can End It}\\[10pt]
  {\fontsize{28}{36}\selectfont\color{white!60} A CALL TO ACTION FOR COMMUNITIES ACROSS AMERICA}
}

% ═══════════════════════════════════════════
% CRISIS STATS BANNER (rows 4-7, span=3)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=24pt, right=24pt, top=10pt, bottom=10pt,
  valign=center, halign=center,
  borderline south={3pt}{0pt}{primary!60},
]{name=crisis, column=1, span=3, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.47\linewidth}\centering
    {\fontsize{96}{116}\selectfont\bfseries\color{statgold}48 MILLION}\\[6pt]
    {\fontsize{32}{40}\selectfont\color{textwarm}Americans face hunger today}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textmuted}including 14 million children}
  \end{minipage}%
  \hfill
  \begin{minipage}[c]{0.47\linewidth}\centering
    {\fontsize{32}{40}\selectfont\color{textmuted} That's 1 in 7 people}\\[4pt]
    {\fontsize{32}{40}\selectfont\color{textmuted} in every community}\\[8pt]
    {\fontsize{36}{44}\selectfont\bfseries\color{primary}This is our moment to act.}
  \end{minipage}
}

% ═══════════════════════════════════════════
% IMPACT METRICS (rows 7-12, 3 columns)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=24pt, bottom=6pt,
  valign=center, halign=center,
  borderline west={5pt}{0pt}{secondary},
]{name=meals, column=1, between=row7 and row12}{
  \centering
  {\fontsize{72}{86}\selectfont\bfseries\color{statgold}5.7}\\[2pt]
  {\fontsize{72}{86}\selectfont\bfseries\color{statgold}BILLION}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{textwarm}Meals Distributed}\\[6pt]
  {\fontsize{24}{30}\selectfont\color{textmuted}Through a nationwide\\network of food banks}
}

\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=24pt, bottom=6pt,
  valign=center, halign=center,
  borderline west={5pt}{0pt}{primary},
]{name=rescued, column=2, between=row7 and row12}{
  \centering
  {\fontsize{72}{86}\selectfont\bfseries\color{statgold}4.3}\\[2pt]
  {\fontsize{72}{86}\selectfont\bfseries\color{statgold}BILLION}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{textwarm}Pounds of Food}\\[2pt]
  {\fontsize{30}{38}\selectfont\color{textwarm}Rescued}\\[6pt]
  {\fontsize{24}{30}\selectfont\color{textmuted}Good food saved\\from going to waste}
}

\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=24pt, bottom=6pt,
  valign=center, halign=center,
  borderline west={5pt}{0pt}{accent},
]{name=network, column=3, between=row7 and row12}{
  \centering
  {\fontsize{72}{86}\selectfont\bfseries\color{statgold}60,000{\fontsize{48}{58}\selectfont\bfseries\color{statgold}+}}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{textwarm}Free Food Programs}\\[6pt]
  {\fontsize{24}{30}\selectfont\color{textmuted}Across {\bfseries\color{statgold}200+} food banks\\in all 50 states \& Puerto Rico}
}

% ═══════════════════════════════════════════
% SECTION: HOW WE UNITE (rows 12-17)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=accent!85!black, colframe=accent!85!black,
  colupper=white, arc=0pt, boxrule=0pt,
  left=24pt, right=24pt, top=8pt, bottom=8pt,
  halign=center, valign=center,
]{name=uniteheader, column=1, span=3, between=row12 and row13}{
  {\fontsize{38}{46}\selectfont\bfseries\color{secondary}HOW WE UNITE COMMUNITIES}
}

\posterbox[warmcard, title={Research-Driven Insights}]{name=pillar1, column=1, between=row13 and row16}{
  \fontsize{28}{36}\selectfont\color{textwarm}
  Listening to neighbors facing hunger. Their stories and ideas shape real solutions.
  \vspace{6pt}
  \colorbox{primary!22}{\parbox{0.90\linewidth}{\fontsize{24}{30}\selectfont\color{textwarm}\centering\itshape ``I've learned how to use whole foods''\\-- Kaycee, Washington\vspace{3pt}}}
}

\posterbox[warmcard, title={Local Relationships}]{name=pillar2, column=2, between=row13 and row16}{
  \fontsize{28}{36}\selectfont\color{textwarm}
  Food bank leaders are passionate community members. Local wisdom is turned into national action every day.
}

\posterbox[warmcard, title={Nationwide Scale}]{name=pillar3, column=3, between=row13 and row16}{
  \fontsize{28}{36}\selectfont\color{textwarm}
  One of the nation's most effective food networks -- moving food quickly, safely, and reliably where it's needed most.
  \vspace{6pt}
  \colorbox{primary!22}{\parbox{0.90\linewidth}{\fontsize{24}{30}\selectfont\color{textwarm}\centering\bfseries All 50 states + Puerto Rico\vspace{3pt}}}
}

\posterbox[warmcard, title={Nutrition for Every Plate}]{name=pillar4, column=1, span=3, between=row16 and row17}{
  \fontsize{28}{36}\selectfont\color{textwarm}\centering
  Making nutritious food accessible so everyone can lead fuller, healthier lives. Providing groceries, recipes, and whole-food education to communities in need.
}

% ═══════════════════════════════════════════
% TAKE ACTION (rows 17-20, span=3)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=accent!85!black, boxrule=0pt, arc=0pt,
  left=24pt, right=24pt, top=10pt, bottom=10pt,
  valign=center, halign=center,
]{name=dollarheader, column=1, span=3, between=row17 and row18}{
  \centering
  {\fontsize{50}{60}\selectfont\bfseries\color{statgold}\$1 = 10 MEALS}\\[3pt]
  {\fontsize{28}{36}\selectfont\color{white!85}Every dollar provides at least 10 meals. \textbf{Gifts are matched for a limited time.}}
}

\posterbox[actioncard, title={}]{name=donate, column=1, between=row18 and row20}{
  \fontsize{32}{40}\selectfont\color{textwarm}\centering
  \vspace{8pt}
  {\fontsize{44}{52}\selectfont\bfseries\color{donategreen}DONATE}\\[10pt]
  {\fontsize{26}{32}\selectfont\color{textmuted}Your gift moves fresh\\food to neighbors fast.\\Every dollar counts.}
}

\posterbox[actioncard, title={}]{name=advocate, column=2, between=row18 and row20}{
  \fontsize{32}{40}\selectfont\color{textwarm}\centering
  \vspace{8pt}
  {\fontsize{44}{52}\selectfont\bfseries\color{donategreen}ADVOCATE}\\[10pt]
  {\fontsize{26}{32}\selectfont\color{textmuted}Urge lawmakers to\\support food programs\\that help neighbors.}
}

\posterbox[actioncard, title={}]{name=volunteer, column=3, between=row18 and row20}{
  \fontsize{32}{40}\selectfont\color{textwarm}\centering
  \vspace{8pt}
  {\fontsize{44}{52}\selectfont\bfseries\color{donategreen}FUNDRAISE}\\[2pt]
  {\fontsize{44}{52}\selectfont\bfseries\color{donategreen}\& VOLUNTEER}\\[10pt]
  {\fontsize{26}{32}\selectfont\color{textmuted}Inspire your community.\\Your hands make\\a difference.}
}

\end{tcbposter}
\end{document}

